#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

MOBILE="$(cd "$(dirname "$0")/.." && pwd)"
ENV_FILE="$HOME/.gradle/gradle.properties"
KEYTOOL="${JAVA_HOME:-$HOME/Android/jdk-17}/bin/keytool"
mkdir -p "$(dirname "$ENV_FILE")"

banner "Nanahoshi → Google Play"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Clave de subida (upload key)"
say "Esta clave firma cada AAB que subes. Google re-firma la app con su propia"
say "clave (Play App Signing); si pierdes esta, soporte de Play puede resetearla."
ask NANAHOSHI_UPLOAD_STORE_FILE "Ruta absoluta del keystore [Enter = $HOME/keys/nanahoshi-upload.jks]:"
NANAHOSHI_UPLOAD_STORE_FILE="${NANAHOSHI_UPLOAD_STORE_FILE:-$HOME/keys/nanahoshi-upload.jks}"
NANAHOSHI_UPLOAD_STORE_FILE="${NANAHOSHI_UPLOAD_STORE_FILE/#\~/$HOME}"
NANAHOSHI_UPLOAD_KEY_ALIAS=upload
if [[ -f "$NANAHOSHI_UPLOAD_STORE_FILE" ]]; then
  note "Ya existe: $NANAHOSHI_UPLOAD_STORE_FILE (no se toca)."
else
  ask KEY_OWNER "Nombre que aparecerá en el certificado (ej. tu nombre o Nanahoshi):"
  mkdir -p "$(dirname "$NANAHOSHI_UPLOAD_STORE_FILE")"
  step "keytool te pedirá una contraseña dos veces. Elige una larga y guárdala."
  note "Sin barra invertida (\\): gradle.properties la trata como escape."
  "$KEYTOOL" -genkeypair -v -keystore "$NANAHOSHI_UPLOAD_STORE_FILE" \
    -alias "$NANAHOSHI_UPLOAD_KEY_ALIAS" -keyalg RSA -keysize 2048 -validity 10000 \
    -dname "CN=${KEY_OWNER:-Nanahoshi}"
  chmod 600 "$NANAHOSHI_UPLOAD_STORE_FILE"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Conectar la clave a Gradle"
say "Se guarda en $ENV_FILE (fuera del repo), que lee bun run aab."
for attempt in 1 2 3 4; do
  if [[ $attempt == 4 ]]; then
    warn "Demasiados intentos. Vuelve a correr el asistente cuando la tengas."
    exit 1
  fi
  ask_secret NANAHOSHI_UPLOAD_STORE_PASSWORD "Contraseña del keystore (no se muestra):"
  if NANAHOSHI_KS_PASS="$NANAHOSHI_UPLOAD_STORE_PASSWORD" "$KEYTOOL" -list \
    -keystore "$NANAHOSHI_UPLOAD_STORE_FILE" -storepass:env NANAHOSHI_KS_PASS \
    -alias "$NANAHOSHI_UPLOAD_KEY_ALIAS" >/dev/null 2>&1; then
    printf '  %s✓ contraseña correcta%s\n' "$GREEN" "$RESET"
    break
  fi
  warn "La contraseña no abre el keystore (o el alias no es 'upload'). Prueba otra vez."
done
write_env NANAHOSHI_UPLOAD_STORE_FILE "$NANAHOSHI_UPLOAD_STORE_FILE"
write_env NANAHOSHI_UPLOAD_KEY_ALIAS "$NANAHOSHI_UPLOAD_KEY_ALIAS"
write_env NANAHOSHI_UPLOAD_STORE_PASSWORD "$NANAHOSHI_UPLOAD_STORE_PASSWORD"
# PKCS12 keystores use one password for the store and the key.
write_env NANAHOSHI_UPLOAD_KEY_PASSWORD "$NANAHOSHI_UPLOAD_STORE_PASSWORD"
chmod 600 "$ENV_FILE"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Respaldo"
say "Si pierdes el keystore o la contraseña no podrás publicar actualizaciones"
say "hasta que soporte de Play resetee la clave (tarda días)."
step "Copia $NANAHOSHI_UPLOAD_STORE_FILE a un lugar fuera de este PC (USB, nube cifrada)."
step "Guarda la contraseña en tu gestor de contraseñas."
note "Nunca lo subas a git: apps/mobile/.gitignore ya ignora *.jks."
pause "¿Hecho? Enter para seguir"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Versión"
current_version=$(node -p "require('$MOBILE/app.json').expo.version")
current_code=$(node -p "require('$MOBILE/app.json').expo.android.versionCode")
say "Actual: version $current_version, versionCode $current_code."
note "versionCode debe subir en cada AAB que subas; 1 está bien para el primero."
printf '  %sNueva version%s %s[Enter = %s]%s ' "$BOLD" "$RESET" "$DIM" "$current_version" "$RESET"
read -r new_version || true
new_version="${new_version:-$current_version}"
printf '  %sNuevo versionCode%s %s[Enter = %s]%s ' "$BOLD" "$RESET" "$DIM" "$current_code" "$RESET"
read -r new_code || true
new_code="${new_code:-$current_code}"
if [[ "$new_version" != "$current_version" || "$new_code" != "$current_code" ]]; then
  NEW_VERSION="$new_version" NEW_CODE="$new_code" node -e '
    const fs = require("fs"), p = process.argv[1];
    const d = JSON.parse(fs.readFileSync(p, "utf8"));
    d.expo.version = process.env.NEW_VERSION;
    d.expo.android.versionCode = Number(process.env.NEW_CODE);
    fs.writeFileSync(p, `${JSON.stringify(d, null, "\t")}\n`);
  ' "$MOBILE/app.json"
  printf '  %s✓ app.json%s → %s (%s)\n' "$GREEN" "$RESET" "$new_version" "$new_code"
else
  note "Sin cambios."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Compilar el AAB"
say "Compila las 4 arquitecturas con R8; tarda unos 15 minutos."
AAB="$MOBILE/dist/nanahoshi-${new_version}-${new_code}.aab"
if confirm "¿Compilar ahora?"; then
  (cd "$MOBILE" && bun run aab) || warn "El build falló; revisa el log de arriba."
fi
if [[ -f "$AAB" ]]; then
  printf '  %s✓ listo%s %s\n' "$GREEN" "$RESET" "$AAB"
else
  SKIPPED+=("Compilar el AAB: bun run --cwd apps/mobile aab")
  warn "No hay AAB todavía; compílalo antes de la etapa 9."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Crear la app en Play Console"
open_url "https://play.google.com/console"
step "Botón 'Crear app' (Create app)."
step "Nombre: Nanahoshi · idioma predeterminado · Tipo: App · Gratis."
step "Acepta las declaraciones (políticas y leyes de exportación) y crea."
note "El package (app.nanahoshi.mobile) queda fijado con el primer AAB: no se puede cambiar."
pause "¿Creada? Enter para seguir"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Contenido de la app (Policy → App content)"
say "Política de privacidad: Play exige una URL pública. El repo no tiene una aún."
ask PRIVACY_URL "URL de tu política de privacidad (Enter si aún no la tienes):"
[[ -z "${PRIVACY_URL:-}" ]] && SKIPPED+=("Publicar una política de privacidad y ponerla en App content")
step "App access: 'Toda o parte de la funcionalidad está restringida'. Los revisores"
step "  necesitan un servidor de prueba accesible desde internet + usuario y"
step "  contraseña de demo, con instrucciones (dirección del servidor, iniciar sesión)."
step "Ads: No contiene anuncios."
step "Content rating: responde el cuestionario (app de lectura; sin chat ni contenido público entre usuarios)."
step "Target audience: elige rangos de adultos; marcar menores de 13 activa la política de Familias."
step "Data safety: la app no tiene analítica ni crash reporting; los datos van al"
step "  servidor que el propio usuario aloja. Muchas apps self-hosted declaran"
step "  'no se recopilan datos'; revisa la guía de Google antes de confirmar."
step "Government apps / Financial / Health: No."
pause "¿Completado? Enter para seguir"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Permisos de servicio en primer plano"
say "La app usa dos servicios en primer plano; Play pide declararlos (App content →"
say "Foreground service permissions) con una descripción y un video corto."
step "Media playback: reproducción de audiolibros con controles en la notificación."
step "Data sync: descarga de libros/audiolibros para leer sin conexión, con progreso en la notificación."
step "Graba un video de cada uno en el teléfono (reproduce un audiolibro; descarga un libro)"
step "  y súbelo a YouTube como no listado; pega esos enlaces en el formulario."
pause "¿Declarados? Enter para seguir"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Primera release (prueba cerrada)"
say "Cuentas personales nuevas: prueba cerrada con 12+ testers durante 14 días"
say "seguidos antes de poder pedir acceso a producción."
step "Testing → Closed testing → Create track (o usa 'Alpha')."
step "Testers: crea una lista de emails (12+) o un Google Group."
step "Create new release. Si pregunta por la clave de firma, deja la que genera Google."
step "Sube: $AAB"
step "Notas de la versión, Next, Save, Send for review."
note "Opcional: Internal testing primero (sin revisión, minutos) para probar el AAB tú mismo."
pause "¿Enviada a revisión? Enter para terminar"

finish
say "Para cada actualización: sube versionCode en apps/mobile/app.json y corre bun run --cwd apps/mobile aab."
